def skill():
    rem = -351
    s = {}
    for n in range(9, 0, -1):
        w = 3*2**(n - 1)
        s[n] = w if rem > 0 else -w
        rem -= s[n]
    assert rem == 0
    return s[2] + s[4] + s[6] + s[8]

def standard():
    import itertools
    res = set()
    for signs in itertools.product((1, -1), repeat=9):
        if sum(sg*3*2**i for i, sg in enumerate(signs)) == -351:
            res.add(sum(signs[i - 1]*3*2**(i - 1) for i in (2, 4, 6, 8)))
    assert len(res) == 1
    return list(res)[0]

def unique():
    return [standard()]
